import type { SessionApi } from "../state/session";

export function Settings(props: { session: SessionApi }) {
  const s = props.session;
  return (
    <section aria-label="Preferências">
      <h2>Preferências</h2>
      <label>
        Tema
        <select
          value={s.theme}
          onChange={(e) => s.setTheme(e.target.value as "light" | "dark" | "auto")}
        >
          <option value="auto">Automático</option>
          <option value="light">Claro</option>
          <option value="dark">Escuro</option>
        </select>
      </label>
      <label>
        Visualização
        <select
          value={s.viewMode}
          onChange={(e) => s.setViewMode(e.target.value as "source" | "preview" | "split")}
        >
          <option value="split">Dividida</option>
          <option value="source">Fonte</option>
          <option value="preview">Preview</option>
        </select>
      </label>
    </section>
  );
}
